from flask import Flask, request, jsonify
import requests

app = Flask(__name__)

@ app.route('/get_route', methods=['GET'])
def get_route():
    route_id = request.args.get('route_id')
    cache_key = f"route_{route_id}"

    # Verificar si la respuesta está en el cache
    if cache_key in app.cache:
        response = app.cache.get(cache_key)
    else:
        response = requests.get(f"https://api.omniroute.com/route/{route_id}")
        if response.status_code == 200:
            app.cache.set(cache_key, response.json(), timeout=3600)  # Cache por 1 hora
        else:
            return jsonify({"error": "Route not found"}), 404

    return jsonify(response.json())
```

